import{_ as e,o as p,c as a,a5 as n}from"./chunks/framework.BvXk9IVy.js";const h=JSON.parse('{"title":"《三体》读后记","description":"","frontmatter":{"title":"《三体》读后记"},"headers":[],"relativePath":"novels/santi.md","filePath":"novels/santi.md","lastUpdated":1791895356000}'),o={name:"novels/santi.md"};function s(i,t,d,r,_,l){return p(),a("div",null,[...t[0]||(t[0]=[n('<h1 id="《三体》读后记" tabindex="-1">《三体》读后记</h1><blockquote><p>我们一直以为自己在仰望，其实只是站在一粒尘埃上。</p></blockquote><h2 id="尺度这件事" tabindex="-1">尺度这件事</h2><p>科幻小说最容易翻车的地方，是把想象写成数字。这本书最厉害的不是数字，是它让你先接受一个日常的、可以理解的处境，然后一点一点把镜头拉到外面去，直到你忽然意识到刚才那个处境有多小。</p><p>那种感觉很难描述。不是被震住了，更像站在一块地上忽然发现脚下是空的——原来我们习以为常的一切，只是恰好还没被外面打扰。</p><h2 id="黑暗森林是一种感觉" tabindex="-1">黑暗森林是一种感觉</h2><p>后来大家总在讨论这本书里的那些设定成不成立，猎人也好，猜疑链也好，能不能推出来。</p><p>我读的时候没想这些。我只觉得它写出了一种情绪：<strong>在一片安静里，任何声音都可能是危险</strong>。</p><p>宇宙的沉默既是慈悲也是警告。这句话作为逻辑未必站得住，但作为一种感受，它在我心里留住了。就像很多人讲不清楚为什么怕黑，但都真的怕过。</p><h2 id="那天晚上" tabindex="-1">那天晚上</h2><p>读完最后一章已经过了十二点。我关了灯，出门站了一会儿。</p><p>冬天的星星不多。以前抬头看天，想的都是好看和遥远；那天晚上我第一次觉得，那种安静是有点可怕的——人类所有的争执、骄傲、自以为想明白了的道理，都发生在一个连尘埃都算不上的地方。</p><p>站了十几分钟就回屋了，因为冷。回屋之后也没多想什么，只是把书合上，放回架子上。</p><h2 id="留下的东西" tabindex="-1">留下的东西</h2><p>隔了一阵再想起这本书，我发现自己记住的不是情节和设定，而是一个动作：抬头。</p><p>一本小说未必能改掉一个人的习惯，但它在某天晚上让我抬头看了很久。它没让我懂得宇宙，只是让我再看天的时候，比从前安静一点。</p>',16)])])}const m=e(o,[["render",s]]);export{h as __pageData,m as default};
